pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ModifierEntrancy} from "../src/ModifierEntrancy.sol";

contract InvMutTest is Test {
    ModifierEntrancy c;
    function setUp() public { c = new ModifierEntrancy(); }

    function testFuzz_property(address actor1, address actor2) public {
        vm.assume(actor1 != address(0));
        vm.assume(actor2 != address(0));
        vm.assume(actor1 != actor2);

        BankLike helper1 = new BankLike();
        BankLike helper2 = new BankLike();

        vm.prank(address(helper1));
        try c.airDrop() {
        } catch {
        }

        bool ok;
        vm.prank(address(helper2));
        try c.airDrop() { ok = true; } catch { ok = false; }

        assertTrue(ok);
    }
}

contract BankLike {
    function supportsToken() external pure returns (bytes32) {
        return keccak256(abi.encodePacked("Nu Token"));
    }
}
